// Internship Inbox — renders postings.json / outreach.json (regenerated by
// main.py every run). Triage and outreach state live in this browser's
// localStorage; Export/Import moves it between devices.

const STORAGE_KEY = "internship-inbox-v1";
const PAGE_SIZE = 150;

// Triage categories. A posting with none of these is uncategorized and sits in the Inbox.
const STATUS_LABELS = {
  to_apply: "To apply",
  applied: "Applied",
  read: "Read",
  ineligible: "Ineligible",
  not_interested: "Not interested",
};
const OUTREACH_LABELS = {
  todo: "Not contacted",
  contacted: "Contacted",
  replied: "Replied",
  follow_up: "Follow up",
};
const MONTHS = {
  jan: "Jan", feb: "Feb", mar: "Mar", apr: "Apr", may: "May", jun: "Jun",
  jul: "Jul", aug: "Aug", sep: "Sep", oct: "Oct", nov: "Nov", dec: "Dec",
};

let postings = [];
let contacts = [];
let state = loadState();
let previousVisit = state.lastVisit || "";
let allShown = PAGE_SIZE;
let inboxShown = PAGE_SIZE;
let nofitShown = PAGE_SIZE;
let statusFilter = "";
let lastAction = null;
let toastTimer = null;

// ---------- state ----------

function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    return { postings: {}, outreach: {}, lastVisit: "", prefs: {}, ...parsed };
  } catch {
    return { postings: {}, outreach: {}, lastVisit: "", prefs: {} };
  }
}

function saveState() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    // Storage unavailable (private window, blocked): the page still works
    // for this session, it just won't remember.
  }
}

function statusOf(p) {
  return (state.postings[p.link] || {}).status || "";
}

function setStatus(p, status) {
  const before = state.postings[p.link] ? { ...state.postings[p.link] } : null;
  if (status) {
    state.postings[p.link] = { status, at: new Date().toISOString().slice(0, 10) };
  } else {
    delete state.postings[p.link];
  }
  saveState();
  render();
  if (status) {
    showToast(`${STATUS_LABELS[status]}: ${p.company}`, () => {
      if (before) state.postings[p.link] = before;
      else delete state.postings[p.link];
      saveState();
      render();
    });
  }
}

// ---------- data ----------

async function load() {
  try {
    const [pRes, oRes] = await Promise.all([
      fetch("postings.json", { cache: "no-store" }),
      fetch("outreach.json", { cache: "no-store" }).catch(() => null),
    ]);
    const pData = await pRes.json();
    postings = pData.postings || [];
    if (oRes && oRes.ok) contacts = (await oRes.json()).contacts || [];
    const updated = pData.generated_at ? new Date(pData.generated_at) : null;
    document.getElementById("updated").textContent =
      `${postings.filter((p) => p.active).length} open internships · updated ` +
      (updated ? updated.toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" }) : "—");
  } catch (e) {
    document.getElementById("updated").textContent =
      "Couldn't load postings.json — serve this folder over HTTP (python -m http.server -d docs).";
    return;
  }

  // "New" = first seen since the previous visit; remember this visit for next time.
  state.lastVisit = new Date().toISOString().slice(0, 10);
  saveState();

  fillCountryFilter();
  document.getElementById("i-sort").value = state.prefs.inboxSort || "score";
  document.getElementById("i-role").value = state.prefs.inboxRole || "";
  document.getElementById("i-country").value = state.prefs.inboxCountry || "";
  render();
}

function isNew(p) {
  return previousVisit && p.first_seen && p.first_seen > previousVisit;
}

// ---------- rendering ----------

function render() {
  renderInbox();
  renderTodo();
  renderAll();
  renderOutreach();
}

function renderInbox() {
  const targetOnly = val("i-role") === "match";
  const country = val("i-country");
  const uncategorized = sortRows(
    postings.filter((p) => p.active && !statusOf(p) && (!targetOnly || p.role_match)
      && (!country || p.country === country)),
    val("i-sort"));
  const fits = uncategorized.filter((p) => p.summer_fit !== "no");
  const noFit = uncategorized.filter((p) => p.summer_fit === "no");

  fillList("inbox-list", fits.slice(0, inboxShown), "inbox",
    "Inbox zero 🎉 — every open posting has a category. Browse everything under All.");
  document.getElementById("inbox-more").hidden = fits.length <= inboxShown;
  fillList("inbox-nofit-list", noFit.slice(0, nofitShown), "inbox", "Nothing here.");
  document.getElementById("inbox-nofit-more").hidden = noFit.length <= nofitShown;
  document.getElementById("inbox-nofit").hidden = noFit.length === 0;
  setCount("count-inbox", fits.length);
  setCount("count-nofit", noFit.length);
}

function renderTodo() {
  // Still-open postings first; closed ones stay listed (dimmed) so they don't vanish silently.
  const rows = postings.filter((p) => statusOf(p) === "to_apply");
  rows.sort((a, b) => Number(b.active) - Number(a.active));
  fillList("todo-list", rows, "todo",
    "Nothing to apply to yet — mark postings To apply from the Inbox.");
  setCount("count-todo", rows.filter((p) => p.active).length);
}

function renderAll() {
  const q = val("f-search").toLowerCase();
  const country = val("f-country");
  const summer = val("f-summer");
  const role = val("f-role");
  const showClosed = document.getElementById("f-closed").checked;

  const base = postings.filter((p) => {
    if (!showClosed && !p.active) return false;
    if (country && p.country !== country) return false;
    if (summer && p.summer_fit !== summer) return false;
    if (role === "match" && !p.role_match) return false;
    if (q && !`${p.company} ${p.role} ${p.location}`.toLowerCase().includes(q)) return false;
    return true;
  });
  renderStatusChips(base);
  const rows = sortRows(
    base.filter((p) => !statusFilter || (statusOf(p) || "none") === statusFilter),
    val("f-sort"));

  document.getElementById("all-summary").textContent =
    `${rows.length} of ${postings.length} postings`;
  fillList("all-list", rows.slice(0, allShown), "all", "No postings match these filters.");
  document.getElementById("all-more").hidden = rows.length <= allShown;
  setCount("count-all", postings.filter((p) => p.active).length);
}

// Category chips for the All tab; counts reflect the other active filters.
function renderStatusChips(rows) {
  const counts = { "": rows.length, none: 0 };
  for (const p of rows) {
    const s = statusOf(p) || "none";
    counts[s] = (counts[s] || 0) + 1;
  }
  const options = [["", "All"], ["none", "Uncategorized"], ...Object.entries(STATUS_LABELS)];
  const group = document.getElementById("f-status");
  group.replaceChildren();
  for (const [value, label] of options) {
    const b = document.createElement("button");
    b.type = "button";
    b.setAttribute("aria-pressed", String(statusFilter === value));
    b.append(label);
    const count = document.createElement("span");
    count.className = "count";
    count.textContent = String(counts[value] || 0);
    b.append(count);
    b.addEventListener("click", () => {
      statusFilter = value;
      allShown = PAGE_SIZE;
      renderAll();
    });
    group.append(b);
  }
}

function sortRows(rows, by) {
  // postings.json is already in recommendation order; "date" re-sorts newest first.
  if (by !== "date") return rows;
  return [...rows].sort((a, b) => effectiveDate(b).localeCompare(effectiveDate(a)) || b.score - a.score);
}

function fillList(id, rows, mode, emptyText) {
  const list = document.getElementById(id);
  list.replaceChildren();
  if (!rows.length) {
    const li = document.createElement("li");
    li.className = "empty";
    li.textContent = emptyText;
    list.append(li);
    return;
  }
  for (const p of rows) list.append(postingCard(p, mode));
}

function postingCard(p, mode) {
  const node = document.getElementById("posting-tpl").content.firstElementChild.cloneNode(true);
  if (!p.active) node.classList.add("closed");

  const score = node.querySelector(".score");
  score.textContent = p.score;
  if (p.score >= 50) score.classList.add("high");

  const link = node.querySelector(".role");
  link.href = p.link;
  link.textContent = p.role;
  node.querySelector(".new-badge").hidden = !isNew(p);

  const company = node.querySelector(".company");
  if (p.priority === "high") {
    const star = document.createElement("span");
    star.className = "star";
    star.textContent = "★ ";
    star.title = "Priority company";
    company.append(star);
  }
  company.append(p.company);

  const posted = effectiveDate(p);
  node.querySelector(".meta").textContent = [
    p.location,
    posted ? `posted ${posted}` : "",
    p.source,
    p.active ? "" : `closed (last seen ${p.last_seen})`,
  ].filter(Boolean).join(" · ");

  const badges = node.querySelector(".badges");
  const status = statusOf(p);
  if (status) badges.append(badge(STATUS_LABELS[status], "status"));
  badges.append(summerBadge(p));
  if (p.degree_req === "phd") badges.append(badge("PhD required", "bad"));
  if (p.degree_req === "masters") badges.append(badge("Master's required", "warn"));
  if (p.degree_req === "any") badges.append(badge("Bachelor's OK", "good"));
  if (p.summer_program) badges.append(badge("Summer program", "good"));
  if (!p.role_match) badges.append(badge("other role"));
  if (p.chem_bio) badges.append(badge("chem/bio", "good"));

  const actions = node.querySelector(".actions");
  if (mode === "inbox") {
    actions.append(
      actionButton("To apply", () => setStatus(p, "to_apply"), "primary"),
      actionButton("Applied", () => setStatus(p, "applied")),
      actionButton("Ineligible", () => setStatus(p, "ineligible")),
      actionButton("Not interested", () => setStatus(p, "not_interested")),
      actionButton("Read", () => setStatus(p, "read")),
    );
  } else if (mode === "todo") {
    actions.append(
      actionButton("Applied", () => setStatus(p, "applied"), "primary"),
      actionButton("Ineligible", () => setStatus(p, "ineligible")),
      actionButton("Not interested", () => setStatus(p, "not_interested")),
      actionButton("Back to inbox", () => setStatus(p, "")),
    );
  } else {
    actions.append(statusSelect(p));
  }
  return node;
}

function summerBadge(p) {
  const bits = [];
  if (p.duration_months) bits.push(`${p.duration_months} mo`);
  if (p.start_hint && p.start_hint !== "summer") bits.push(`starts ${MONTHS[p.start_hint] || p.start_hint}`);
  const detail = bits.length ? ` (${bits.join(", ")})` : "";
  if (p.summer_fit === "yes") return badge(`Summer ✓${detail}`, "good");
  if (p.summer_fit === "no") return badge(`Not summer${detail}`, "bad");
  return badge(`Summer ?${detail}`);
}

function statusSelect(p) {
  const select = document.createElement("select");
  select.setAttribute("aria-label", `Status for ${p.role}`);
  select.append(new Option("Uncategorized", ""));
  for (const [value, label] of Object.entries(STATUS_LABELS)) select.append(new Option(label, value));
  select.value = statusOf(p);
  select.addEventListener("change", () => setStatus(p, select.value));
  return select;
}

// ---------- outreach ----------

function renderOutreach() {
  const filter = val("o-status");
  const list = document.getElementById("outreach-list");
  list.replaceChildren();
  const rows = contacts.filter((c) => !filter || outreachStatus(c) === filter);
  setCount("count-outreach", contacts.filter((c) => outreachStatus(c) === "todo").length);

  if (!rows.length) {
    const li = document.createElement("li");
    li.className = "empty";
    li.textContent = contacts.length
      ? "No contacts with this status."
      : "No outreach entries yet — add them to outreach.yaml.";
    list.append(li);
    return;
  }

  for (const c of rows) {
    const li = document.createElement("li");
    li.className = "card";

    const score = document.createElement("div");
    score.className = "score";
    score.textContent = c.open_postings_total;
    score.title = "Open postings at this company";
    if (c.open_postings_total) score.classList.add("high");

    const body = document.createElement("div");
    body.className = "body";
    const title = document.createElement("div");
    title.className = "title-row";
    const name = document.createElement(c.link ? "a" : "span");
    name.className = "role";
    name.textContent = c.name ? `${c.name} — ${c.contact_role}` : c.contact_role || c.company;
    if (c.link) {
      name.href = c.link;
      name.target = "_blank";
      name.rel = "noopener";
    }
    title.append(name);

    const company = document.createElement("div");
    company.className = "company";
    if (c.priority === "high") {
      const star = document.createElement("span");
      star.className = "star";
      star.textContent = "★ ";
      company.append(star);
    }
    company.append(c.company);

    const meta = document.createElement("div");
    meta.className = "meta";
    meta.textContent = c.why;
    if (c.careers_url) {
      meta.append(" · ");
      const a = document.createElement("a");
      a.href = c.careers_url;
      a.target = "_blank";
      a.rel = "noopener";
      a.textContent = "careers page";
      meta.append(a);
    }

    body.append(title, company, meta);
    if (c.notes) {
      const notes = document.createElement("div");
      notes.className = "meta";
      notes.textContent = c.notes;
      body.append(notes);
    }
    if (c.open_postings.length) {
      const ul = document.createElement("ul");
      ul.className = "postings-mini";
      for (const op of c.open_postings) {
        const item = document.createElement("li");
        const a = document.createElement("a");
        a.href = op.link;
        a.target = "_blank";
        a.rel = "noopener";
        a.textContent = op.role;
        item.append(a);
        ul.append(item);
      }
      body.append(ul);
    }

    const note = document.createElement("textarea");
    note.placeholder = "Your notes (who you messaged, when, what they said)…";
    note.value = (state.outreach[c.id] || {}).note || "";
    note.addEventListener("change", () => {
      state.outreach[c.id] = { ...(state.outreach[c.id] || {}), note: note.value };
      saveState();
    });
    body.append(note);

    const actions = document.createElement("div");
    actions.className = "actions";
    const select = document.createElement("select");
    select.setAttribute("aria-label", `Outreach status for ${c.company}`);
    for (const [value, label] of Object.entries(OUTREACH_LABELS)) select.append(new Option(label, value));
    select.value = outreachStatus(c);
    select.addEventListener("change", () => {
      state.outreach[c.id] = {
        ...(state.outreach[c.id] || {}),
        status: select.value,
        at: new Date().toISOString().slice(0, 10),
      };
      saveState();
      renderOutreach();
    });
    actions.append(select);
    const at = (state.outreach[c.id] || {}).at;
    if (at && outreachStatus(c) !== "todo") {
      const since = document.createElement("span");
      since.className = "meta";
      since.textContent = `since ${at}`;
      actions.append(since);
    }

    li.append(score, body, actions);
    list.append(li);
  }
}

function outreachStatus(c) {
  return (state.outreach[c.id] || {}).status || "todo";
}

// ---------- helpers ----------

function effectiveDate(p) {
  return p.posted_date || p.first_seen || "";
}

function badge(text, kind) {
  const span = document.createElement("span");
  span.className = kind ? `badge ${kind}` : "badge";
  span.textContent = text;
  return span;
}

function actionButton(label, onClick, cls) {
  const b = document.createElement("button");
  b.type = "button";
  b.textContent = label;
  if (cls) b.className = cls;
  b.addEventListener("click", onClick);
  return b;
}

function setCount(id, n) {
  document.getElementById(id).textContent = n ? String(n) : "";
}

function val(id) {
  return document.getElementById(id).value;
}

function fillCountryFilter() {
  // Italy first (the priority), then alphabetical.
  const countries = [...new Set(postings.map((p) => p.country).filter(Boolean))]
    .sort((a, b) => (b === "Italy") - (a === "Italy") || a.localeCompare(b));
  for (const id of ["f-country", "i-country"]) {
    const select = document.getElementById(id);
    for (const c of countries) select.append(new Option(c, c));
  }
}

function showToast(text, undo) {
  lastAction = undo;
  document.getElementById("toast-text").textContent = text;
  document.getElementById("toast-undo").hidden = !undo;
  const toast = document.getElementById("toast");
  toast.hidden = false;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { toast.hidden = true; lastAction = null; }, 5000);
}

// ---------- wiring ----------

document.querySelectorAll(".tabs button").forEach((btn) => {
  btn.addEventListener("click", () => {
    document.querySelectorAll(".tabs button").forEach((b) =>
      b.setAttribute("aria-selected", String(b === btn)));
    document.querySelectorAll(".tab-panel").forEach((panel) => {
      panel.hidden = panel.id !== `tab-${btn.dataset.tab}`;
    });
    try { sessionStorage.setItem("tab", btn.dataset.tab); } catch {}
  });
});

["f-search", "f-country", "f-summer", "f-role", "f-sort", "f-closed"].forEach((id) => {
  document.getElementById(id).addEventListener("input", () => { allShown = PAGE_SIZE; renderAll(); });
});
["i-sort", "i-role", "i-country"].forEach((id) => {
  document.getElementById(id).addEventListener("input", () => {
    state.prefs = {
      ...state.prefs, inboxSort: val("i-sort"), inboxRole: val("i-role"), inboxCountry: val("i-country"),
    };
    saveState();
    inboxShown = nofitShown = PAGE_SIZE;
    renderInbox();
  });
});
document.getElementById("inbox-more").addEventListener("click", () => { inboxShown += PAGE_SIZE; renderInbox(); });
document.getElementById("inbox-nofit-more").addEventListener("click", () => { nofitShown += PAGE_SIZE; renderInbox(); });
document.getElementById("o-status").addEventListener("input", renderOutreach);
document.getElementById("all-more").addEventListener("click", () => { allShown += PAGE_SIZE; renderAll(); });

document.getElementById("toast-undo").addEventListener("click", () => {
  if (lastAction) lastAction();
  lastAction = null;
  document.getElementById("toast").hidden = true;
});

document.getElementById("export-btn").addEventListener("click", () => {
  const blob = new Blob([JSON.stringify(state, null, 1)], { type: "application/json" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `internship-inbox-${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(a.href);
});

document.getElementById("import-input").addEventListener("change", async (e) => {
  const file = e.target.files[0];
  if (!file) return;
  try {
    const imported = JSON.parse(await file.text());
    // Merge: imported entries win, local-only entries are kept.
    state = {
      ...state,
      postings: { ...state.postings, ...(imported.postings || {}) },
      outreach: { ...state.outreach, ...(imported.outreach || {}) },
    };
    saveState();
    render();
    showToast(`Imported ${Object.keys(imported.postings || {}).length} posting statuses`, null);
  } catch {
    showToast("That file isn't a valid export.", null);
  }
  e.target.value = "";
});

try {
  const savedTab = sessionStorage.getItem("tab");
  if (savedTab) document.querySelector(`.tabs button[data-tab="${savedTab}"]`)?.click();
} catch {}

load();
